#include "radio_app_view.h"
#include "cc1101.h"
#include "display.h"
#include "nrf24_activity.h"
#include <stdio.h>
#define BG 0x0000U
#define SUBDUED 0x03F0U
#define TEXT 0xBDF7U
#define DIM 0x7BEFU
#define YELLOW 0xFFE0U
#define LIMIT 0xFD20U
#define GRAPH 0x03E0U
#define PEAK 0x07FFU
#define APP_COLUMN_DIVIDER_X 198
#define APP_RIGHT_COLUMN_X 205
static void mhz(char *b,size_t n,uint32_t k){snprintf(b,n,"%lu.%03lu",(unsigned long)(k/1000U),(unsigned long)(k%1000U));}
void radio_app_view_cc1101_spectrum(const uint8_t *fast,const uint8_t *slow,size_t count,uint32_t low,uint32_t high,bool detected,const cc1101_fingerprint_t *devices,size_t device_count){display_clear(BG);display_draw_text(8,7,"CC1101",SUBDUED,2U);char a[24],b[24],line[64];mhz(a,sizeof(a),low);mhz(b,sizeof(b),high);snprintf(line,sizeof(line),"%s - %s MHz",a,b);display_draw_text(8,30,line,DIM,1U);if(!detected){display_draw_text(8,70,"CC1101 NOT DETECTED",YELLOW,1U);display_draw_text(8,126,"CENTER: SETTINGS",SUBDUED,1U);(void)display_present();return;}const int x0=8,y0=48,w=APP_COLUMN_DIVIDER_X-14,h=92;display_fill_rect(x0,y0+h,w,1,DIM);for(size_t i=0;i<count;i++){int x=x0+(int)((i*(size_t)(w-1))/(count>1U?count-1U:1U));int bh=(int)fast[i]*(h-3)/255;if(bh>0)display_fill_rect(x,y0+h-bh,2,bh,GRAPH);int py=y0+h-(int)slow[i]*(h-3)/255;if(py<y0)py=y0;display_fill_rect(x,py,2,2,PEAK);}display_fill_rect(APP_COLUMN_DIVIDER_X,36,1,RFSCOUT_DISPLAY_HEIGHT-36,DIM);display_draw_text(APP_RIGHT_COLUMN_X,43,"LIKELY DEVICES",SUBDUED,1U);if(0U==device_count){display_draw_text(APP_RIGHT_COLUMN_X,66,"No strong",DIM,1U);display_draw_text(APP_RIGHT_COLUMN_X,78,"fingerprint",DIM,1U);display_draw_text(APP_RIGHT_COLUMN_X,90,"yet",DIM,1U);}else{for(size_t i=0;i<device_count&&i<CC1101_FINGERPRINT_MAX;i++){int y=64+(int)i*18;const char *label=devices[i].label[0]?devices[i].label:cc1101_activity_fingerprint_name(devices[i].type);snprintf(line,sizeof(line),"%.15s %u%%",label,(unsigned)devices[i].confidence);display_draw_text(APP_RIGHT_COLUMN_X,y,line,i==0U?TEXT:DIM,1U);snprintf(line,sizeof(line),"%lu.%03lu %ddBm",(unsigned long)(devices[i].center_khz/1000U),(unsigned long)(devices[i].center_khz%1000U),(int)devices[i].peak_rssi);display_draw_text(APP_RIGHT_COLUMN_X,y+9,line,DIM,1U);}}display_draw_text(8,148,"FAST ACTIVITY / PEAK HOLD",DIM,1U);display_draw_text(250,148,"SETTINGS",SUBDUED,1U);(void)display_present();}
void radio_app_view_cc1101_menu(unsigned selected,bool editing,const char *profile,uint32_t low,uint32_t high,uint32_t step,size_t samples,bool limit_reached){display_clear(BG);display_draw_text(8,7,"CC1101 SETTINGS",SUBDUED,2U);const char *labels[]={"PROFILE","LOW","HIGH","STEP","BACK"};char val[32];for(unsigned i=0;i<5;i++){int y=36+(int)i*23;bool active=i==selected;uint16_t accent=(active&&editing&&limit_reached)?LIMIT:YELLOW;display_draw_text(8,y,active?(editing?"*":">"):" ",active?accent:DIM,1U);display_draw_text(22,y,labels[i],active?TEXT:DIM,1U);val[0]='\0';if(i==0)snprintf(val,sizeof(val),"%s",profile);else if(i==1)snprintf(val,sizeof(val),"%lu.%03lu MHz",(unsigned long)(low/1000),(unsigned long)(low%1000));else if(i==2)snprintf(val,sizeof(val),"%lu.%03lu MHz",(unsigned long)(high/1000),(unsigned long)(high%1000));else if(i==3)snprintf(val,sizeof(val),"%lu kHz",(unsigned long)step);if(val[0]){if(active&&editing){display_fill_rect(126,y-4,174,18,accent);display_draw_text(130,y,val,BG,1U);}else display_draw_text(130,y,val,active?YELLOW:DIM,1U);}}snprintf(val,sizeof(val),"%u/%u SAMPLES",(unsigned)samples,(unsigned)CC1101_MAX_SWEEP_SAMPLES);display_draw_text(8,146,val,limit_reached?LIMIT:DIM,1U);display_draw_text(8,158,limit_reached?"SWEEP LIMIT 128":(editing?"TURN: CHANGE       CENTER: DONE":"TURN: SELECT      CENTER: ENTER"),limit_reached?LIMIT:(editing?YELLOW:SUBDUED),1U);(void)display_present();}
void radio_app_view_nrf24_spectrum(const uint8_t *fast,const uint8_t *slow,size_t count,uint8_t low,uint8_t high,bool detected,const nrf24_fingerprint_t *devices,size_t device_count){display_clear(BG);display_draw_text(8,7,"nRF24",SUBDUED,2U);char line[64];snprintf(line,sizeof(line),"CH %u-%u   %u-%u MHz",(unsigned)low,(unsigned)high,(unsigned)(2400U+low),(unsigned)(2400U+high));display_draw_text(8,30,line,DIM,1U);if(!detected){display_draw_text(8,70,"nRF24 NOT DETECTED",YELLOW,1U);(void)display_present();return;}const int x0=8,y0=48,w=APP_COLUMN_DIVIDER_X-14,h=92;display_fill_rect(x0,y0+h,w,1,DIM);size_t span=(size_t)(high-low)+1U;for(size_t i=0;i<span;i++){size_t ch=(size_t)low+i;if(ch>=count)break;int x=x0+(int)((i*(size_t)(w-1))/(span>1U?span-1U:1U));int bh=(int)fast[ch]*(h-3)/255;if(bh>0)display_fill_rect(x,y0+h-bh,2,bh,GRAPH);int py=y0+h-(int)slow[ch]*(h-3)/255;if(py<y0)py=y0;display_fill_rect(x,py,2,2,PEAK);}display_fill_rect(APP_COLUMN_DIVIDER_X,36,1,RFSCOUT_DISPLAY_HEIGHT-36,DIM);display_draw_text(APP_RIGHT_COLUMN_X,43,"LIKELY DEVICES",SUBDUED,1U);if(0U==device_count){display_draw_text(APP_RIGHT_COLUMN_X,66,"No strong",DIM,1U);display_draw_text(APP_RIGHT_COLUMN_X,78,"fingerprint",DIM,1U);display_draw_text(APP_RIGHT_COLUMN_X,90,"yet",DIM,1U);}else{for(size_t i=0;i<device_count&&i<5U;i++){int y=64+(int)i*18;const char *label=devices[i].label[0]?devices[i].label:nrf24_activity_fingerprint_name(devices[i].type);snprintf(line,sizeof(line),"%.15s %u%%",label,(unsigned)devices[i].confidence);display_draw_text(APP_RIGHT_COLUMN_X,y,line,i==0?TEXT:DIM,1U);if(devices[i].packets>0U){snprintf(line,sizeof(line),"CH%u %lu pkt",(unsigned)devices[i].channel,(unsigned long)devices[i].packets);display_draw_text(APP_RIGHT_COLUMN_X,y+9,line,DIM,1U);}}}display_draw_text(8,148,"FAST ACTIVITY / PEAK HOLD",DIM,1U);display_draw_text(250,148,"SETTINGS",SUBDUED,1U);(void)display_present();}
void radio_app_view_nrf24_menu(unsigned selected,bool editing,uint8_t low,uint8_t high,uint16_t dwell){display_clear(BG);display_draw_text(8,7,"nRF24 SETTINGS",SUBDUED,2U);const char *labels[]={"LOW CH","HIGH CH","DWELL","BACK"};char val[32];for(unsigned i=0;i<4;i++){int y=42+(int)i*28;bool active=i==selected;display_draw_text(8,y,active?(editing?"*":">"):" ",active?YELLOW:DIM,1U);display_draw_text(22,y,labels[i],active?TEXT:DIM,1U);val[0]='\0';if(i==0)snprintf(val,sizeof(val),"%u / %u MHz",(unsigned)low,(unsigned)(2400U+low));else if(i==1)snprintf(val,sizeof(val),"%u / %u MHz",(unsigned)high,(unsigned)(2400U+high));else if(i==2)snprintf(val,sizeof(val),"%u us",(unsigned)dwell);if(val[0]){if(active&&editing){display_fill_rect(126,y-4,174,18,YELLOW);display_draw_text(130,y,val,BG,1U);}else display_draw_text(130,y,val,active?YELLOW:DIM,1U);}}display_draw_text(8,158,editing?"TURN: CHANGE       CENTER: DONE":"TURN: SELECT      CENTER: ENTER",editing?YELLOW:SUBDUED,1U);(void)display_present();}
